package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

public class ProofMemo078Test {
    private JSONObject binding(){return new JSONObject().put("study","owned").put("code","original").put("source","A");}
    @Test public void exactBytesReuseAndReturnedReceiptsCannotMutateTrust()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace.json"),"original");var m=new ProofMemo078(root);var n=new AtomicInteger();var a=m.check(binding(),List.of(f),true,n::incrementAndGet);assertEquals("full",a.getString("mode"));a.getJSONArray("evidence").getJSONObject(0).put("sha256","forged");assertEquals("hit",m.check(binding(),List.of(f),true,n::incrementAndGet).getString("mode"));assertEquals(1,n.get());}
    @Test public void uncachedControlNeitherPrimesNorEvictsMemo()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace"),"original");var m=new ProofMemo078(root);var n=new AtomicInteger();assertEquals("full",m.check(binding(),List.of(f),false,n::incrementAndGet).getString("mode"));assertEquals(0,m.size());m.check(binding(),List.of(f),true,n::incrementAndGet);m.check(binding(),List.of(f),false,n::incrementAndGet);assertEquals("hit",m.check(binding(),List.of(f),true,n::incrementAndGet).getString("mode"));assertEquals(3,n.get());}
    @Test public void sameLengthAndRestoredTimestampCannotHideChangedEvidence()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace"),"original");var time=Files.getLastModifiedTime(f);var m=new ProofMemo078(root);m.check(binding(),List.of(f),true,()->{});Files.writeString(f,"tampered");Files.setLastModifiedTime(f,time);assertThrows(IllegalStateException.class,()->m.check(binding(),List.of(f),true,()->{throw new IllegalStateException("Full proof rejects changed trace");}));assertEquals(0,m.size());}
    @Test public void changedCodeOrSourceRequiresACompleteCheck()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace"),"original");var m=new ProofMemo078(root);var n=new AtomicInteger();m.check(binding(),List.of(f),true,n::incrementAndGet);assertEquals("full",m.check(binding().put("code","new"),List.of(f),true,n::incrementAndGet).getString("mode"));assertEquals("full",m.check(binding().put("source","B"),List.of(f),true,n::incrementAndGet).getString("mode"));assertEquals(3,n.get());}
    @Test public void changedDuringAuditAndFailedAuditCannotInstall()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace"),"original");var m=new ProofMemo078(root);assertThrows(IllegalStateException.class,()->m.check(binding(),List.of(f),true,()->Files.writeString(f,"changed")));assertEquals(0,m.size());assertThrows(IllegalStateException.class,()->m.check(binding(),List.of(f),true,()->{throw new IllegalStateException("failure");}));assertEquals(0,m.size());}
    @Test public void restartedProcessIsColdAndCacheRemainsBounded()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace"),"original");var m=new ProofMemo078(root);for(int i=0;i<17;i++)m.check(binding().put("item",i),List.of(f),true,()->{});assertEquals(16,m.size());assertEquals("full",m.check(binding().put("item",0),List.of(f),true,()->{}).getString("mode"));assertEquals("full",new ProofMemo078(root).check(binding().put("item",0),List.of(f),true,()->{}).getString("mode"));}
    @Test public void missingDuplicateOutsideAndEmptyEvidenceRefuse()throws Exception{var root=Files.createTempDirectory("memo078-");var f=Files.writeString(root.resolve("trace"),"original");var outside=Files.createTempFile("outside078-",".json");var m=new ProofMemo078(root);assertThrows(IllegalArgumentException.class,()->m.check(binding(),List.of(),true,()->{}));assertThrows(IllegalArgumentException.class,()->m.check(binding(),List.of(f,f),true,()->{}));assertThrows(IllegalStateException.class,()->m.check(binding(),List.of(outside),true,()->{}));m.check(binding(),List.of(f),true,()->{});Files.delete(f);assertThrows(IllegalStateException.class,()->m.check(binding(),List.of(f),true,()->{}));}
    @Test public void redirectedParentCannotSupplyOwnedEvidence()throws Exception{var root=Files.createTempDirectory("memo078-");var outside=Files.createTempDirectory("other078-");Files.writeString(outside.resolve("trace"),"original");var link=root.resolve("redirect");if(System.getProperty("os.name").startsWith("Windows")){var proc=new ProcessBuilder("pwsh","-NoProfile","-Command","New-Item -ItemType Junction -Path '"+link.toString().replace("'","''")+"' -Target '"+outside.toString().replace("'","''")+"' | Out-Null").redirectErrorStream(true).start();String output=new String(proc.getInputStream().readAllBytes());assertEquals(output,0,proc.waitFor());}else Files.createSymbolicLink(link,outside);assertThrows(IllegalStateException.class,()->new ProofMemo078(root).check(binding(),List.of(link.resolve("trace")),true,()->{}));}
}
